{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@mazac-fox/opencode-fleet-contracts",
  "version": "0.1.0",
  "description": "Canonical ID, telemetry, artifact, and health contracts shared across the OpenCode plugin fleet. Consumed directly by CLIs/daemons; re-exported from @mazac-fox/opencode-host-adapter for plugin authors.",
  "type": "module",
  "license": "MIT",
  "private": false,
  "repository": {
    "type": "git",
    "url": "git+https://github.com/jackmazac/opencode-fleet-contracts.git"
  },
  "keywords": ["opencode", "opencode-plugin", "fleet", "contracts", "telemetry", "correlation"],
  "exports": {
    ".": "./src/index.ts",
    "./ids": "./src/ids.ts",
    "./context": "./src/context.ts",
    "./telemetry": "./src/telemetry.ts",
    "./artifacts": "./src/artifacts.ts",
    "./health": "./src/health.ts"
  },
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "src",
    "!src/**/*.test.ts",
    "README.md",
    "LICENSE"
  ],
  "dependencies": {
    "ulid": "^3.0.1"
  },
  "devDependencies": {
    "@tsconfig/bun": "latest",
    "@types/bun": "latest",
    "@types/node": "latest",
    "@typescript/native-preview": "latest"
  },
  "scripts": {
    "typecheck": "tsgo --noEmit",
    "test": "bun test",
    "check": "bun run typecheck && bun test"
  }
}
